  21: public final class VehiclePropertyBackend implements ManagerRegistry.Backend {
  22:     private final CarPropertyService properties;
  23:     public VehiclePropertyBackend(CarPropertyService properties){this.properties=properties;}
  24:     @Override public ManagerResult call(ManagerCall call){
  25:         if("get".equals(call.operation)){
  26:             int propertyId=call.args.getInt("property_id");int areaId=call.args.getInt("area_id");
  27:             CarPropertyValue value=properties.getPropertySafe(propertyId,areaId);
  28:             Bundle output=new Bundle();output.putString("value",String.valueOf(value));
  29:             return new ManagerResult(value!=null,value==null?"unavailable":null,output);
  30:         }
  31:         if("permission".equals(call.operation)){
  32:             Bundle output=new Bundle();output.putString("read_permission",properties.getReadPermission(call.args.getInt("property_id")));
  33:             return new ManagerResult(true,null,output);
  34:         }
  35:         return new ManagerResult(false,"unsupported vehicle operation: "+call.operation,null);
  36:     }
  37: }
