  17: package com.cockpitbench.managerkit;
  18: import android.os.Bundle;
  19: import java.lang.reflect.Method;import java.util.HashMap;import java.util.Map;
  20: public final class PlatformManagerFallback {
  21:     private final Map<String,String> backends=new HashMap<>();
  22:     public PlatformManagerFallback(){
  23:         backends.put("8155","com.vendor.legacy.CockpitManagerBridge");
  24:         backends.put("8295","com.vendor.modern.CockpitManagerBridge");
  25:         backends.put("xinqing","com.partner.vehicle.ManagerBridge");
  26:     }
  27:     public ManagerResult call(ManagerCall call){
  28:         String platform=call.args.getString("platform","8155");String className=backends.get(platform);
  29:         if(className==null)return new ManagerResult(false,"unsupported platform: "+platform,null);
  30:         try{
  31:             Class<?> type=Class.forName(className);Object instance=type.getConstructor().newInstance();
  32:             Method method=type.getMethod(call.operation,Bundle.class);method.setAccessible(true);
  33:             Object value=method.invoke(instance,call.args);Bundle output=new Bundle();output.putString("value",String.valueOf(value));
  34:             return new ManagerResult(true,null,output);
  35:         }catch(ReflectiveOperationException|RuntimeException error){
  36:             return new ManagerResult(false,error.getClass().getSimpleName()+": "+error.getMessage(),null);
  37:         }
  38:     }
  39: }
