  19: import android.os.IBinder;
  20: import java.lang.reflect.Method;
  21: import java.util.Set;
  22: 
  23: /** Narrow compatibility seam for product branches whose builtin API differs by platform. */
  24: public final class PlatformVehicleAccess {
  25:     private static final Set<String> ALLOWED_SERVICES = Set.of(
  26:             "android.hardware.automotive.vehicle.IVehicle/default");
  27: 
  28:     public IBinder waitFor(String serviceName) {
  29:         if (!ALLOWED_SERVICES.contains(serviceName)) {
  30:             throw new SecurityException("Unapproved vehicle service: " + serviceName);
  31:         }
  32:         try {
  33:             Class<?> helper = Class.forName("android.car.builtin.os.ServiceManagerHelper");
  34:             Method wait = helper.getMethod("waitForDeclaredService", String.class);
  35:             return (IBinder) wait.invoke(null, serviceName);
  36:         } catch (ReflectiveOperationException error) {
  37:             throw new IllegalStateException("AAOS vehicle service helper unavailable", error);
  38:         }
  39:     }
  40: }
