 182:     private void fetchAllPropConfigs() {
 183:         synchronized (mLock) {
 184:             if (mAllProperties.size() != 0) { // already set
 185:                 Slogf.i(CarLog.TAG_HAL, "fetchAllPropConfigs already fetched");
 186:                 return;
 187:             }
 188:         }
 189:         HalPropConfig[] configs;
 190:         try {
 191:             configs = mHalClient.getAllPropConfigs();
 192:             if (configs == null || configs.length == 0) {
 193:                 Slogf.e(CarLog.TAG_HAL, "getAllPropConfigs returned empty configs");
 194:                 return;
 195:             }
 196:         } catch (RemoteException | ServiceSpecificException e) {
 197:             throw new RuntimeException("Unable to retrieve vehicle property configuration", e);
 198:         }
 199: 
 200:         synchronized (mLock) {
 201:             // Create map of all properties
 202:             for (HalPropConfig p : configs) {
 203:                 if (DBG) {
 204:                     Slogf.i(CarLog.TAG_HAL, "Add config for prop:"
 205:                             + Integer.toHexString(p.getPropId()) + " config:" + p.toString());
 206:                 }
 207:                 mAllProperties.put(p.getPropId(), p);
 208:             }
 209:         }
 210:     }
